printBirthday()

def fibonacci(n):
  if n==1:  # first value
    return 0
  elif n==2:  # second value
    return 1
  else:
    return fibonacci(n-1)+fibonacci(n-2) # call the function twice, recursively

for i in range(1,11):
  print(fibonacci(i),"",end="")
print()

def calcTax(income):
  if income<=100000:
    return 0.15*income
  else:
    return 15000+0.25*(income-100000)

print(f'${calcTax(50000):.2f}')
print(f'${calcTax(100000):.2f}')
print(f'${calcTax(150000):.2f}')

def factorial(n):
  result=1
  for i in range(2,n+1):
    result*=i
  return(result)

for i in range(1,11):
  print(factorial(i),"",end="")

def factorial_recursive(n):
  if n==1: return 1
  else: return n*factorial_recursive(n-1)

for i in range(1,11):
  print(factorial_recursive(i),"",end="")

def pigLatin(w):
  atBeginning=True
  newWord=""
  for c in w:
    if atBeginning:
      if (c.lower() in "aeiou"):
        return w+"yay"
      else:
        ending=c+"ay"
        atBeginning=False
    else:
      newWord+=c
  return newWord+ending

print(pigLatin("Tall"))
print(pigLatin("ant"))
print(pigLatin("slant"))  # this version doesn't handle consonant clusters properly
